def build(lang,d):
    output=base.ROOT/f'public/assets/funnel/{lang}/flownexa-guia-direct.pdf'
    output.parent.mkdir(parents=True,exist_ok=True)
    c=canvas.Canvas(str(output),pagesize=(base.W,base.H),pageCompression=1)
    c.setTitle(d['title']+' | FlowNexa');c.setAuthor('FlowNexa');c.setSubject(d['free'])
    def foot(num,dark=False):
        c.setFillColor(white if dark else base.MUTED);c.setFont('Guide',8)
        c.drawString(base.M,31,'FLOWNEXA / '+lang.upper());c.drawRightString(base.W-base.M,31,f'{num:02d} / 06')
        c.linkURL('https://flownex.online',(base.M,23,base.M+200,42),relative=0)
    def top(num,index):
        c.setFillColor(white);c.rect(0,0,base.W,base.H,fill=1,stroke=0)
        base.logo(c,base.M,base.H-65,25);base.para(c,'FlowNexa',base.M+34,base.H-43,size=13,bold=True)
        y=base.para(c,d['labels'][index].upper(),base.M,base.H-101,size=9,bold=True,color=base.PURPLE)
        y=base.para(c,d['heads'][index],base.M,y-18,size=27,leading=32,bold=True,color=base.NAVY)
        y=base.para(c,d['intros'][index],base.M,y-16,size=11,leading=17,color=base.MUTED)
        foot(num);return y-22
    def card(y,num,data):
        title,when,script,after=data
        y=base.para(c,f'{num:02d} / '+escape(title),base.M,y,size=16,leading=21,bold=True,color=base.PURPLE)
        y=base.para(c,escape(when),base.M,y-8,size=10,leading=15,color=base.MUTED)
        y=base.para(c,'“'+escape(script)+'”',base.M,y-13,size=12,leading=18,color=base.NAVY)
        y=base.para(c,'<b>'+d['after']+':</b> '+escape(after),base.M,y-12,size=10,leading=15,color=base.MUTED)
        assert y>66,(lang,num,y)
        return y-27
    c.setFillColor(base.NAVY);c.rect(0,0,base.W,base.H,fill=1,stroke=0)
    base.logo(c,base.M,base.H-88,38,base.HexColor('#c5a4ff'));base.para(c,'FlowNexa',base.M+51,base.H-56,size=19,color=white,bold=True)
    y=base.para(c,d['free'],base.M,680,size=10,leading=15,color=base.HexColor('#cfb8ff'),bold=True)
    y=base.para(c,d['title'],base.M,y-34,size=39,leading=46,color=white,bold=True)
    y=base.para(c,d['subtitle'],base.M,y-25,size=13,leading=21,color=base.HexColor('#ded5ed'))
    base.para(c,d['audience'],base.M,245,size=13,leading=20,color=white)
    base.para(c,d['adapt'],base.M,147,size=10,leading=16,color=base.HexColor('#c7bcd7'));foot(1,True);c.showPage()
    for i in range(3):
        y=top(i+2,i)
        for j in range(2): y=card(y,i*2+j+1,d['cards'][i*2+j])
        c.showPage()
    y=top(5,3);y=card(y,7,d['cards'][6])
    for index in range(4):
        y=base.para(c,f'{index+1:02d}  →  '+escape(d['cards'][index][0]),base.M,y,size=13,leading=20,bold=True,color=base.NAVY)-17
    c.showPage()
    y=top(6,4)
    for item in d['check']:
        y=base.para(c,'□ '+escape(item),base.M,y,size=10,leading=15)-12
    y=base.para(c,d['cta'],base.M,y-8,size=17,leading=22,bold=True,color=base.PURPLE)
    y=base.para(c,d['ctacopy'],base.M,y-9,size=11,leading=17)
    y=base.para(c,'<link href="https://flownex.online" color="#663bc8"><b>flownex.online →</b></link>',base.M,y-12,size=12)-18
    y=base.para(c,d['note'],base.M,y,size=8,leading=12,color=base.MUTED)
    assert y>56,(lang,'checklist',y)
    c.showPage();c.save();print(output)

if __name__=='__main__':
    for lang,data in COPY.items():build(lang,data)
